class TreeNode:
    def __init__(self, value=0, left=None, right=None):
        self.value = value
        self.left = left
        self.right = right

def build_tree(values):
    if not values:
        return None
    root = TreeNode(values[0])
    queue = [root]
    i = 1
    while queue and i < len(values):
        node = queue.pop(0)
        if i < len(values):
            value = values[i]
            i += 1
            if value is not None:
                node.left = TreeNode(value)
                queue.append(node.left)
        if i < len(values):
            value = values[i]
            i += 1
            if value is not None:
                node.right = TreeNode(value)
                queue.append(node.right)
    return root

def unlink_tree(node):
    if node is None:
        return
    unlink_tree(node.left)
    unlink_tree(node.right)
    node.left = None
    node.right = None

def prepare(raw):
    root = build_tree(raw[0])
    def finish(result):
        unlink_tree(root)
        return result
    return [root], finish

