def diameter_of_binary_tree(root):
    best = 0
    def height(node):
        nonlocal best
        if node is None:
            return 0
        left = height(node.left)
        right = height(node.right)
        if left + right > best:
            best = left + right
        return 1 + max(left, right)
    height(root)
    return best

bruteForceCode:
def diameter_of_binary_tree(root):
    def depth(node):
        if node is None:
            return 0
        return 1 + max(depth(node.left), depth(node.right))
    best = 0
    stack = [root] if root is not None else []
    while stack:
        node = stack.pop()
        if node is None:
            continue
        candidate = depth(node.left) + depth(node.right)
        if candidate > best:
            best = candidate
        stack.append(node.left)
        stack.append(node.right)
    return best
